# Permission-aware traversal: prune branches the identity cannot read before descending.
tree = {'pub': {'a.txt': None}, 'priv': {'b.txt': None}}
acl = [['/pub*', '*', ['read']], ['/priv*', 'amy', ['read']], ['/priv*', 'bob', []]]
def can(identity, path, need="read"):
    # most-specific matching rule wins
    best, perm = -1, set()
    for pattern, who, allows in acl:
        if who in (identity, "*") and (path == pattern or path.startswith(pattern.rstrip("*"))):
            if len(pattern) > best: best, perm = len(pattern), set(allows)
    return need in perm
def walk(node, path, identity):
    for name, sub in sorted(node.items()):
        p = path + "/" + name
        if not can(identity, p):
            print(f"  SKIP {p} (denied)")
            continue
        print(f"  VISIT {p}")
        if isinstance(sub, dict): walk(sub, p, identity)
print("traversal as amy:")
walk(tree, "", "amy")

